      bits_read = 0
      if bits_read + 144 > num_bits, do: throw(:invalid)
      v = rd(data, bits_read, 16)
      bits_read = bits_read + 16
      v_synchronize_sequence = v
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      w = v
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      w = w ||| v <<< 32
      v_current_frame = w
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      w = v
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      w = w ||| v <<< 32
